UPDATE T_JOURNAL_ERROR
   SET STATUS = 'R', LAST_RETRY_DT = CURRENT_TIMESTAMP
 WHERE SEQ = #{seq}

UPDATE T_JOURNAL_ERROR
   SET STATUS = 'F', RETRY_CNT = #{retryCnt}, LAST_RETRY_DT = CURRENT_TIMESTAMP
 WHERE SEQ = #{seq}

UPDATE T_JOURNAL_ERROR
   SET RETRY_CNT = NVL(RETRY_CNT, 0) + 1, LAST_RETRY_DT = CURRENT_TIMESTAMP
 WHERE SEQ = #{seq}
